const c=(e,t)=>{if(!e)return[];const s=String(e.role||"").toUpperCase();if(s!=="MANAGER"&&s!=="EMPLOYEE")return[];const n=e.assigned_works||[];if(!Array.isArray(n))return[];const a=[];n.forEach(r=>{if(r.work_type===t){const i=r.branch_id||r.branch;(i||i===0)&&a.push({id:String(i),name:r.branch_name||`Branch #${i}`,is_default:!1})}});const o=new Set;return a.filter(r=>o.has(r.id)?!1:(o.add(r.id),!0))},d=(e,t)=>{if(!t||t.length===0)return e;const s=new Set(t.map(n=>String(n.id)));return e.filter(n=>s.has(String(n.id)))};export{d as f,c as g};
